for origin, target in LINKS:
    m = by_id['jogos-'+origin]
    target = 'jogos-'+target
    assert target in by_id and target != m['id']
    if target not in m['relations']:
        m['relations'].append(target)
        m['relationTypes'][target] = 'thematic'

assert len(memories) == 73 and len(by_id) == len(memories)
assert all(len(m['content']) < 700 for m in memories)
payload = dict(format='harness-aurora-memories', version=1, pack='aurora-jogos-v1', curatedAt='2026-09-20', memories=memories)
directory = ROOT / 'knowledge'
directory.mkdir(exist_ok=True)
target = directory / 'jogos-v1.json'
target.write_text(json.dumps(payload, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
print(json.dumps({'file':str(target),'memories':len(memories),'relations':sum(len(m['relations']) for m in memories),'contentChars':sum(len(m['content']) for m in memories)},ensure_ascii=False))
